from typing import Optional

from fastapi import Cookie, Header, WebSocket


async def get_cookie_or_client(
    websocket: WebSocket,
    session: Optional[str] = Cookie(None),
    x_client: Optional[str] = Header(None),
) -> Optional[str]:
    """
    Return the first available identifier for the client:
    - `session` cookie
    - `X-Client` header
    If neither is present, return ``None``.
    The function **must not** close the websocket – the route decides what to do.
    """
    return session or x_client
