from typing import Optional

from fastapi import APIRouter, Depends, Query, WebSocket

from ..dependencies import get_cookie_or_client

router = APIRouter()


@router.websocket("/items/{item_id}/ws")
async def websocket_endpoint(
    websocket: WebSocket,
    item_id: int,
    q: Optional[str] = Query(None),
    client_id: Optional[str] = Depends(get_cookie_or_client),
):
    """
    WebSocket endpoint.
    - Accepts the connection.
    - Sends a notice when no session cookie / X-Client header is provided.
    - Echoes received messages together with the ``item_id`` and optional query ``q``.
    """
    await websocket.accept()

    # Inform the client if we could not identify it.
    if client_id is None:
        await websocket.send_text(
            "❗️ No session cookie nor X-Client header"
        )
    else:
        await websocket.send_text(
            f"✅ Session/Client identifier received: {client_id}"
        )

    # Normal message loop.
    while True:
        try:
            data = await websocket.receive_text()
        except Exception:
            # Client closed the connection.
            break

        response = f"Message text was: {data}"
        if q:
            response += f", query param: {q}"
        response += f", for item ID: {item_id}"
        await websocket.send_text(response)
