```python
import asyncio

import pytest
import websockets

BASE_URL = "ws://127.0.0.1:8000"


@pytest.fixture(scope="module")
def event_loop():
    """Create an event loop for the whole test module."""
    loop = asyncio.get_event_loop_policy().new_event_loop()
    yield loop
    loop.close()


@pytest.mark.asyncio
async def test_ws_without_cookie():
    """
    Connect without any cookie/header.
    Expect the first server message to contain the warning about missing identifier.
    """
    uri = f"{BASE_URL}/items/1/ws"
    async with websockets.connect(uri) as ws:
        # The server should send a notice immediately.
        notice = await ws.recv()
        assert "No session cookie" in notice

        # Send a test message and verify the echo format.
        await ws.send("hello")
        response = await ws.recv()
        assert "Message text was: hello" in response
        assert "for item ID: 1" in response


@pytest.mark.asyncio
async def test_ws_with_cookie():
    """
    Connect with a ``session`` cookie.
    The server must acknowledge the identifier and then behave normally.
    """
    uri = f"{BASE_URL}/items/42/ws?q=testquery"
    extra_headers = [("Cookie", "session=test-session-id")]
    async with websockets.connect(uri, extra_headers=extra_headers) as ws:
        # Acknowledge message.
        ack = await ws.recv()
        assert "Session/Client identifier received" in ack
        assert "test-session-id" in ack

        # Normal echo test.
        await ws.send("world")
        response = await ws.recv()
        assert "Message text was: world" in response
        assert "query param: testquery" in response
        assert "for item ID: 42" in response
